/**
 * Shared styles for the Base UI flavour of Mallow.
 *
 * Mallow is light and soft. A surface is a white card with a soft plum
 * shadow, a lilac option track, or a chosen option in a light violet tint
 * inside a violet ring. An action is the solid violet primary or the quiet
 * white secondary, both rounded rectangles. This file mirrors `../components/_shared.ts` and
 * is copied rather than imported, because the registry ships this folder on
 * its own. Base UI marks state with bare attributes (data-checked,
 * data-highlighted, data-pressed, data-disabled, data-popup-open), so the
 * state selectors here read those.
 *
 * Form fields MUST import `formFieldBase`. Do NOT copy-paste these strings
 * into a component.
 */

/** The violet focus line every interactive part shares, drawn with no offset. */
export const focusRing = "outline-none focus-visible:ring-2 focus-visible:ring-ring";

/** The focus line for buttons, set off from the button by a card-coloured gap. */
export const controlFocusRing =
  "outline-none focus-visible:ring-2 focus-visible:ring-ring focus-visible:ring-offset-2 focus-visible:ring-offset-card";

/** The violet primary finish that checked controls share, so they read as one material with the primary Button. */
export const primaryFinish = "bg-(image:--violet-face) text-primary-foreground shadow-(--violet-edge)";

/** The violet primary a touch lighter under the pointer. */
export const primaryFinishHover = "hover:bg-(image:--violet-face-hover)";

/** The quiet white action used by secondary buttons and quiet tags. */
export const quietFinish =
  "bg-(image:--quiet-face) text-foreground shadow-(--quiet-edge) hover:bg-(image:--quiet-face-hover)";

/** The chosen option, a light violet tint inside a violet ring, that marks the selected option, the active tab and the pressed toggle. */
export const selectedOption = "bg-(--option-face) text-foreground shadow-(--option-edge)";

/** A small white surface with a hairline: avatars, icon tiles and handles that are not a selection. */
export const softPanel = "bg-card text-foreground shadow-(--panel-edge)";

/** The option track, a soft lilac fill that holds a set of options. */
export const optionTrack = "bg-(--option-track) shadow-(--option-track-edge)";

/** The card, a white surface with a hairline and a soft plum shadow. */
export const cardSlab = "bg-card text-card-foreground shadow-(--shadow-card)";

/** A surface nested inside a card, drawn with a hairline and no drop. */
export const surfacePanel = "bg-popover text-card-foreground shadow-(--panel-edge)";

/** The press every button shares: a small scale toward the page. */
export const pressScale =
  "transition-[scale,box-shadow,background-image] duration-fast ease-(--ease-out) active:scale-98 motion-reduce:active:scale-100";

/** The critically damped spring that carries a moving selection fast and never overshoots. */
export const panelSpring = { type: "spring", stiffness: 520, damping: 46, mass: 1 } as const;

/** The softer spring for content that swaps in place. */
export const swapSpring = { type: "spring", stiffness: 420, damping: 38 } as const;

/** The chosen option with a stronger ring on hover, for tags and neutral controls. */
export const selectedLift = `${selectedOption} transition-shadow duration-base ease-(--ease-out) hover:shadow-(--option-edge-hover)`;

/** Base styles every form-field surface shares: a white field with a 0.625rem corner and a 3:1 edge that darkens on hover. */
export const formFieldBase =
  "w-full min-w-0 rounded-lg border border-foreground/55 bg-card px-4 text-base text-foreground shadow-xs " +
  "placeholder:text-muted-foreground " +
  "transition-[box-shadow,border-color] duration-base ease-(--ease-out) " +
  "hover:border-foreground/75 " +
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring " +
  "disabled:cursor-not-allowed disabled:opacity-50 " +
  "data-[disabled]:cursor-not-allowed data-[disabled]:opacity-50";

/** Height and vertical padding for single-line form fields, 3rem to match the button. */
export const formFieldSingleLine = "flex h-12 py-2";

/** Vertical padding and minimum height for multi-line form fields. */
export const formFieldMultiLine = "flex min-h-28 py-3 leading-normal";

/** A field whose popup is open keeps its edge, so it reads as active. */
export const fieldOpen = "data-[popup-open]:border-input";

/** The floating panel every menu, popover, select and tooltip shares: white, with a hairline and a soft drop. */
export const popoverSurface = "rounded-xl bg-popover text-popover-foreground shadow-(--shadow-menu) outline-none";

/** Popups grow from their anchor and fade, and leave the same way. */
export const popupMotion =
  "origin-(--transform-origin) transition-[opacity,scale] duration-fast ease-(--ease-out) " +
  "data-[starting-style]:scale-95 data-[starting-style]:opacity-0 " +
  "data-[ending-style]:scale-95 data-[ending-style]:opacity-0";

/** The popover settles at the base duration, both ways. */
export const popoverMotion =
  "origin-(--transform-origin) transition-[opacity,scale] duration-base ease-(--ease-out) " +
  "data-[starting-style]:scale-95 data-[starting-style]:opacity-0 " +
  "data-[ending-style]:scale-95 data-[ending-style]:opacity-0";

/** A row inside a floating panel that takes the hover tone when highlighted. */
export const menuItemBase =
  "relative flex min-h-9 cursor-default select-none items-center gap-2 rounded-md px-2.5 py-1.5 text-sm outline-none " +
  "transition-colors duration-fast " +
  "data-[highlighted]:bg-accent data-[highlighted]:text-accent-foreground " +
  "data-[disabled]:pointer-events-none data-[disabled]:opacity-50";

/** A checked small control (checkbox box, radio, switch track) in the primary finish. */
export const controlChecked =
  "data-[checked]:bg-(image:--violet-face) data-[checked]:text-primary-foreground data-[checked]:shadow-(--violet-edge)";

/** A pressed toggle or tag, shown as the chosen option inside its track. */
export const pressedOption =
  "data-[pressed]:bg-(--option-face) data-[pressed]:text-foreground data-[pressed]:shadow-(--option-edge)";
